import { test, expect } from '@playwright/test';

test.describe('Order Confirmation After Payment', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display order confirmation after successful payment', async ({ page }) => {
    // Intercept the payment API call
    await page.route('**/api/payment/process', (route) => {
      route.continue();
    });

    // Verify payment form is visible
    const paymentForm = page.getByRole('form', { name: /place order/i });
    await expect(paymentForm).toBeVisible();

    // Fill in payment details using getByLabel
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111111');

    const expiryDateInput = page.getByLabel(/expiry date/i);
    await expiryDateInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    const billingAddressInput = page.getByLabel(/billing address/i);
    await billingAddressInput.fill('123 Main St, Anytown, CA 12345');

    const zipCodeInput = page.getByLabel(/zip code/i);
    await zipCodeInput.fill('12345');

    // Verify payment button is enabled
    const paymentButton = page.getByRole('button', { name: /confirm payment/i });
    await expect(paymentButton).toBeEnabled();

    // Click the payment button
    await paymentButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/order confirmed/i);
    await expect(successMessage).toBeVisible();

    // Verify order details are displayed
    const orderDetails = page.getByText(/order number: 123456789/i);
    await expect(orderDetails).toBeVisible();

    // Verify order confirmation link is present
    const confirmLink = page.getByRole('link', { name: /confirm order/i });
    await expect(confirmLink).toBeVisible();

    // Verify order confirmation modal is visible
    const confirmationModal = page.getByRole('dialog', { name: /order confirmation/i });
    await expect(confirmationModal).toBeVisible();

    // Verify modal is closed when clicking outside
    await confirmationModal.click();
    await expect(confirmationModal).not.toBeVisible();

    // Verify order summary is visible
    const orderSummary = page.getByText(/order summary/i);
    await expect(orderSummary).toBeVisible();

    // Verify order summary contains correct details
    const orderTotal = page.getByText(/total: $100.00/i);
    await expect(orderTotal).toBeVisible();
  });

